  bk_d_agency:["Агентство","Agentlik","Agency"],
  bk_d_ag_data:["Данные, бренд и реквизиты агентства","Agentlik ma’lumotlari, brendi va rekvizitlari","Agency details, branding and requisites"],
  bk_d_order_data:["Пассажиры и контакты заказа","Buyurtma yo‘lovchilari va kontaktlari","Order travellers and contacts"],
  bk_d_balance:["Баланс","Balans","Balance"],
  bk_d_credit:["Кредитный лимит","Kredit limiti","Credit limit"],
  bk_d_orders:["Заказов","Buyurtmalar","Orders"],
  bk_d_dirs:["Направлений","Yo‘nalishlar","Destinations"],
  bk_d_cms:["Содержимое сайта","Sayt mazmuni","Website content"],
  err_bk_dirs:["Копия меняет или удаляет направления. Восстановить её может сотрудник с правом править (а для удаления — удалять) направления.","Nusxa yo‘nalishlarni o‘zgartiradi yoki o‘chiradi. Uni yo‘nalishlarni tahrirlash (o‘chirish uchun — o‘chirish) huquqi bor xodim tiklay oladi.","The backup changes or removes destinations. Only someone allowed to edit (and, to remove them, delete) destinations can restore it."],
  err_bk_cms:["Копия заменяет содержимое сайта. Восстановить её может сотрудник с правом управлять содержимым.","Nusxa sayt mazmunini almashtiradi. Uni mazmunni boshqarish huquqi bor xodim tiklay oladi.","The backup replaces the website content. Only someone allowed to manage content can restore it."],
  err_bk_crm:["Копия меняет лиды, задачи или комментарии CRM. Восстановить её может сотрудник с правом править (а если что-то пропадёт — удалять) в CRM.","Nusxa CRM lidlari, vazifalari yoki izohlarini o‘zgartiradi. Uni CRMda tahrirlash (biror narsa yo‘qolsa — o‘chirish) huquqi bor xodim tiklay oladi.","The backup changes CRM leads, tasks or comments. Only someone allowed to edit (and, if anything disappears, delete) in the CRM can restore it."],
  err_bk_blocks:["Копия меняет список заблокированных клиентов. Восстановить её может сотрудник с правом блокировать клиентов.","Nusxa bloklangan mijozlar ro‘yxatini o‘zgartiradi. Uni mijozlarni bloklash huquqi bor xodim tiklay oladi.","The backup changes the list of blocked customers. Only someone allowed to block customers can restore it."],
  err_bk_ag:["Копия добавляет, убирает, блокирует или разблокирует агентства. Восстановить её может сотрудник с правом управлять агентствами.","Nusxa agentliklarni qo‘shadi, olib tashlaydi, bloklaydi yoki blokdan chiqaradi. Uni agentliklarni boshqarish huquqi bor xodim tiklay oladi.","The backup adds, removes, blocks or unblocks agencies. Only someone allowed to manage agencies can restore it."],
  bk_d_order:["Заказ","Buyurtma","Order"],
  err_bk_ag_new:["Копия заводит новые агентства. Восстановить её может сотрудник с правом заводить агентства.","Nusxa yangi agentliklar qo‘shadi. Uni agentlik qo‘shish huquqi bor xodim tiklay oladi.","The backup adds new agencies. Only someone allowed to create agencies can restore it."],
  err_bk_ag_edit:["Копия меняет данные, бренд или реквизиты агентств. Восстановить её может сотрудник с правом править агентства.","Nusxa agentliklarning ma’lumotlari, brendi yoki rekvizitlarini o‘zgartiradi. Uni agentliklarni tahrirlash huquqi bor xodim tiklay oladi.","The backup changes agency details, branding or requisites. Only someone allowed to edit agencies can restore it."],
  err_bk_orders:["Копия меняет пассажиров или контакты заказов. Восстановить её может сотрудник с правом править заказы.","Nusxa buyurtmalarning yo‘lovchilari yoki kontaktlarini o‘zgartiradi. Uni buyurtmalarni tahrirlash huquqi bor xodim tiklay oladi.","The backup changes order travellers or contacts. Only someone allowed to edit orders can restore it."],
  bk_d_leads:["Лидов CRM","CRM lidlari","CRM leads"],
